import json
import statistics
from collections import defaultdict
from datetime import datetime

from c1_datos import generar

# Precios SUPUESTOS por 1M de tokens (input, cache_read, output)
PRECIOS = {"modelo-std": (2.00, 0.20, 8.00)}

def costo_llm(run):
    u = run["outputs"]["generations"][0][0]["message"]["kwargs"]["usage_metadata"]
    p_in, p_cache, p_out = PRECIOS[run["extra"]["metadata"]["ls_model_name"]]
    cache = (u.get("input_token_details") or {}).get("cache_read", 0)
    return (cache * p_cache + (u["input_tokens"] - cache) * p_in
            + u["output_tokens"] * p_out) / 1_000_000

def por_traza(runs):
    """Junta cada run LLM con su traza: cliente, minuto, modelos, cache_read y costo."""
    trazas = {}
    for r in runs:
        if r["parent_run_id"] is None:
            trazas[r["trace_id"]] = {"customer": r["extra"]["metadata"].get("customer"),
                                     "inicio": datetime.fromisoformat(r["start_time"]),
                                     "modelos": set(), "cache": 0, "costo": 0.0}
    for r in runs:
        if r["run_type"] == "llm":
            t = trazas[r["trace_id"]]
            t["modelos"].add(r["extra"]["metadata"]["ls_model_name"])
            u = r["outputs"]["generations"][0][0]["message"]["kwargs"]["usage_metadata"]
            t["cache"] += (u.get("input_token_details") or {}).get("cache_read", 0)
            t["costo"] += costo_llm(r)
    return list(trazas.values())

trazas = por_traza(generar())     # después del lab: json.load(open("traces.json"))

print("== Por cliente ==")
grupos = defaultdict(list)
for t in trazas:
    grupos[t["customer"]].append(t["costo"])
for cliente, costos in sorted(grupos.items()):
    print(f"{cliente:7} trazas={len(costos):3}  total=${sum(costos):.4f}  "
          f"mediana por traza=${statistics.median(costos):.5f}")

print("== Por bloque de 10 minutos ==")
bloques = defaultdict(list)
for t in trazas:
    bloques[t["inicio"].minute // 10 * 10].append(t)
for b, ts in sorted(bloques.items()):
    modelos = set().union(*(t["modelos"] for t in ts))
    print(f"min {b:2}-{b + 9:2}  trazas={len(ts):2}  modelos={sorted(modelos)}  "
          f"cache_read medio={statistics.mean(t['cache'] for t in ts):6.0f}  "
          f"mediana costo=${statistics.median(t['costo'] for t in ts):.5f}")
